#!/usr/bin/env pwsh
# Generated by Claude Opus 4.8 (claude.ai/code) - 2026-11-13

<#
.SYNOPSIS
  Archive recipe (GFS-Y): keep tiered daily / weekly / yearly copies.
.DESCRIPTION
  An archiver recipe. The engine passes a RecipeContext and runs its 'archive'
  step against the completed set in $ctx.OutDir. Each run is routed to exactly
  one tier, log-driven (never by dir names):
    - yearly, if the log shows no yearly archive this calendar year;
    - else weekly, if the log shows no weekly archive this ISO week;
    - else daily.
  The copy lands in a per-tier directory, then that tier is pruned to keep the
  newest archive of each of the last N PERIODS (not the N most recent copies), so
  extra same-period runs can never erode day/week/year coverage. Log-driven, by the
  recorded ts/path — never by dir names.
  Coverage is the engine's: any archive of the service, whatever its tier, counts
  for the service's targetIntervalHours (a yearly or weekly also covers the day).
  Env (via $ctx):
    ARCHIVE_DEST         (required) destination base dir; the service name is appended.
    ARCHIVE_KEEP_DAILY   (default 2) daily periods to keep.
    ARCHIVE_KEEP_WEEKLY  (default 2) weekly periods to keep.
    ARCHIVE_KEEP_YEARLY  (default 2) yearly periods to keep.
  Layout: <ARCHIVE_DEST>/<service>/<tier>/<runId>/<artifacts>
  Reports { tier, path, pruned } back through $ctx.State.Result so the engine
  can log the tier on service.archived and record each pruned path.
#>

param($Recipe)

if ($null -eq $Recipe) {
    Write-Host 'This is a sequencer recipe; it is loaded by the engine, not run directly.'
    return
}

$Recipe.AddStep('archive', {
    param($ctx)
    # period key for a tier + timestamp (groups archives into their retention period)
    $periodKeyOf = {
        param($tier, [datetime]$ts)
        switch ($tier) {
            'yearly' { 'Y{0:D4}' -f $ts.Year }
            'weekly' { 'W{0:D4}-{1:D2}' -f [System.Globalization.ISOWeek]::GetYear($ts), [System.Globalization.ISOWeek]::GetWeekOfYear($ts) }
            default { 'D{0:yyyyMMdd}' -f $ts }
        }
    }
    $destBase = $ctx.RequireEnv('ARCHIVE_DEST')
    $keepByTier = @{
        yearly = [int]($ctx.EnvValue('ARCHIVE_KEEP_YEARLY', '2'))
        weekly = [int]($ctx.EnvValue('ARCHIVE_KEEP_WEEKLY', '2'))
        daily  = [int]($ctx.EnvValue('ARCHIVE_KEEP_DAILY', '2'))
    }

    $events = $ctx.ReadEvents()
    # prior archives of this service that carry a tier (log is the single source of truth)
    $archived = @($events | Where-Object {
            $_.type -eq 'service.archived' -and $_.svc -eq $ctx.Service -and
            $_.PSObject.Properties['tier'] -and $_.PSObject.Properties['ts']
        })

    # --- route to a tier: first-of-period wins the coarsest empty slot ---
    $now = Get-Date   # local: periods (day, ISO week, year) follow the host's calendar
    $hasYearlyThisYear = @($archived | Where-Object {
            $_.tier -eq 'yearly' -and ([datetime]$_.ts).ToLocalTime().Year -eq $now.Year
        }).Count -gt 0
    if (-not $hasYearlyThisYear) {
        $tier = 'yearly'
    }
    else {
        $isoYear = [System.Globalization.ISOWeek]::GetYear($now)
        $isoWeek = [System.Globalization.ISOWeek]::GetWeekOfYear($now)
        $hasWeeklyThisWeek = @($archived | Where-Object {
                $_.tier -eq 'weekly' -and
                [System.Globalization.ISOWeek]::GetYear(([datetime]$_.ts).ToLocalTime()) -eq $isoYear -and
                [System.Globalization.ISOWeek]::GetWeekOfYear(([datetime]$_.ts).ToLocalTime()) -eq $isoWeek
            }).Count -gt 0
        $tier = if ($hasWeeklyThisWeek) { 'daily' } else { 'weekly' }
    }

    $keep = [math]::Max(1, $keepByTier[$tier])

    # --- copy the set into <dest>/<svc>/<tier>/<runId>/ ---
    $tierDir = Join-Path (Join-Path $destBase $ctx.Service) $tier
    New-Item -ItemType Directory -Force -Path $tierDir | Out-Null
    $stamp = if ($ctx.RunId) { $ctx.RunId } else { Get-Date -Format 'yyyyMMdd-HHmmss' }
    $target = Join-Path $tierDir $stamp
    New-Item -ItemType Directory -Force -Path $target | Out-Null
    Copy-Item -Path (Join-Path $ctx.OutDir '*') -Destination $target -Recurse -Force

    # --- prune this tier: keep the newest archive of each of the last N PERIODS ---
    $prunedPaths = @($events |
            Where-Object { $_.type -eq 'service.archive-pruned' -and $_.PSObject.Properties['path'] } |
            ForEach-Object { $_.path })
    # every live archive of this tier, plus the copy just made (current period)
    $tierArchives = @($events |
            Where-Object {
                $_.type -eq 'service.archived' -and $_.svc -eq $ctx.Service -and
                $_.PSObject.Properties['tier'] -and $_.tier -eq $tier -and
                $_.PSObject.Properties['path'] -and ($prunedPaths -notcontains $_.path)
            } |
            ForEach-Object { [pscustomobject]@{ ts = ([datetime]$_.ts).ToLocalTime(); path = $_.path; isNew = $false } })
    $tierArchives += [pscustomobject]@{ ts = $now; path = $target; isNew = $true }
    foreach ($a in $tierArchives) {
        $a | Add-Member -NotePropertyName periodKey -NotePropertyValue (& $periodKeyOf $tier $a.ts)
    }

    # newest archive per period, then keep the newest $keep periods
    $newestByPeriod = @{}
    foreach ($a in ($tierArchives | Sort-Object ts)) { $newestByPeriod[$a.periodKey] = $a }  # last wins = newest
    $keepPeriods = @($newestByPeriod.Keys | Sort-Object { $newestByPeriod[$_].ts } -Descending | Select-Object -First $keep)

    # measured then deleted; a failed delete is not reported as pruned, so the archive
    # stays live in the log and the next run tries again
    $prunedNow = @()
    $pruneFailed = @()
    foreach ($a in $tierArchives) {
        if ($a.isNew) { continue }   # never prune the copy just made
        $keepThis = ($keepPeriods -contains $a.periodKey) -and ($newestByPeriod[$a.periodKey].path -eq $a.path)
        if (-not $keepThis) {
            $r = $ctx.RemoveTree($a.path)
            if ($r.Ok) {
                $prunedNow += @{ path = [string]$a.path; bytes = $r.Bytes; files = $r.Files }
                Write-Information ("pruned {0} ({1}, {2} files)" -f $a.path, $ctx.SizeText($r.Bytes), $r.Files)
            }
            else {
                $pruneFailed += @{ path = [string]$a.path; error = $r.Error }
                Write-Warning ("prune failed, kept for next run: {0}: {1}" -f $a.path, $r.Error)
            }
        }
    }

    $ctx.State['Result'] = @{ tier = $tier; path = $target; pruned = $prunedNow; pruneFailed = $pruneFailed }
})

# preflight (before any downtime): the destination must be set and reachable — its
# nearest existing ancestor must be a directory, so an unmounted/typo dest is caught
# before the backup runs rather than after.
$Recipe.SetValidate({
    param($ctx)
    $problems = @()
    $dest = $ctx.EnvValue('ARCHIVE_DEST', '')
    if (-not $dest) {
        $problems += 'ARCHIVE_DEST not set'
    }
    else {
        $anc = $dest
        while ($anc -and -not (Test-Path -LiteralPath $anc)) { $anc = Split-Path -Parent $anc }
        if (-not $anc -or -not (Test-Path -LiteralPath $anc -PathType Container)) {
            $problems += "ARCHIVE_DEST unreachable (no existing parent dir): $dest"
        }
    }
    return $problems
})

